#include <mmt_core.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

//each function name should be prefixed by em_
/**
* Return:
* - 0: ok
* - 1: invalid
*/
static inline int em_check_ngap_storm(const void *data) {
    uint64_t count = 0;
    mmt_array_t *trace = (mmt_array_t *)data;
    if (trace == NULL) {
        return 1; // Invalid data
    }
    for (int i = 0; i < mmt_array_size(trace); ++i) {
        const rule_t *rule = mmt_array_get(trace, i);
        if (rule != NULL && rule->property_id == 123) { // Assuming property ID 123 represents NGSetupRequest
            count++;
        }
    }
    return (count > 5); // Define storm threshold as 5 or more NGSetupRequest messages
}
